import { execSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

// `data/core.json` is generated by the root `extract-intl` script and is the
// source file uploaded to the translation service. If it drifts from the
// `messages.ts` files, the translation service drops the missing keys from
// every locale and the shell falls back to default messages at runtime
// (MISSING_TRANSLATION errors). This runs the same `extract-intl` command,
// writing to a temp file, and fails when the committed file differs.

const repoRoot = path.resolve(__dirname, '../../..');
const committedCorePath = path.join(repoRoot, 'packages/i18n/data/core.json');

const readExtractIntlCommand = (): string => {
  const rootPackageJson = JSON.parse(
    fs.readFileSync(path.join(repoRoot, 'package.json'), 'utf8')
  );
  const command: string | undefined = rootPackageJson.scripts?.['extract-intl'];
  if (!command || !/--out-file=\S+/.test(command)) {
    throw new Error(
      'Expected the root `extract-intl` script to write with `--out-file=`.'
    );
  }
  return command;
};

const extractMessages = (): Record<string, unknown> => {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'extract-intl-'));
  const outFile = path.join(tempDir, 'core.json');
  try {
    const command = readExtractIntlCommand().replace(
      /--out-file=\S+/,
      `--out-file=${outFile}`
    );
    execSync(`pnpm exec ${command}`, { cwd: repoRoot, stdio: 'pipe' });
    return JSON.parse(fs.readFileSync(outFile, 'utf8'));
  } finally {
    fs.rmSync(tempDir, { recursive: true, force: true });
  }
};

describe('packages/i18n/data/core.json', () => {
  let extracted: Record<string, unknown>;
  let committed: Record<string, unknown>;

  beforeAll(() => {
    extracted = extractMessages();
    committed = JSON.parse(fs.readFileSync(committedCorePath, 'utf8'));
  }, 120_000);

  it('contains every message defined in the messages.ts files', () => {
    const missing = Object.keys(extracted).filter((id) => !(id in committed));
    // Run `pnpm extract-intl` to regenerate `data/core.json`.
    expect(missing).toEqual([]);
  });

  it('contains no messages that are no longer defined', () => {
    const stale = Object.keys(committed).filter((id) => !(id in extracted));
    // Run `pnpm extract-intl` to regenerate `data/core.json`.
    expect(stale).toEqual([]);
  });

  it('matches the extracted default messages and descriptions', () => {
    // Run `pnpm extract-intl` to regenerate `data/core.json`.
    expect(committed).toEqual(extracted);
  });
});
